/* Child-friendly page markup. Data and handlers are owned by app.js. */
function gameAvatarMarkup(u){return typeof gameCharacter==='function'?gameCharacter(u):`<img src="assets/lynx-guide.png" alt="Тим — проводник" width="190" height="230">`}
function gameRegionPage(u){
 const p=kidProgress(u),next=lessons.findIndex((_,i)=>!u.completed.includes(i));
 return `<div class="game-world"><section class="game-region-hero"><div><h2>Привет, Южный Урал!</h2><p>Здесь горы хранят истории, ветер играет на курае, а лес пахнет мёдом. Данияр и его бабушка готовятся к празднику. Поможем им и узнаем этот край поближе?</p><div class="game-actions"><a class="kid-primary" href="#story">${u.story?.step?'Продолжить историю':'В гости к Данияру'} ${kidIcon('arrow')}</a><a class="btn secondary" href="#map">К карте</a></div><div class="game-stats"><div><strong>${p.studied} / 5</strong><span>открытий в дневнике</span></div><div><strong>~10 мин</strong><span>на путешествие</span></div><div><strong>${p.xp}</strong><span>твоего опыта</span></div></div></div><div class="game-region-art"><img src="assets/ural-postcard.jpg" alt="Река, лес и горы Южного Урала на иллюстрированной открытке" width="700" height="390"></div></section><section class="game-route"><h2>Твой маршрут</h2><p>Выбирай любую остановку. Читай, пробуй и забирай открытие в дневник.</p><nav class="game-trail" aria-label="Пять остановок маршрута">${lessons.map((l,i)=>`<a class="${u.completed.includes(i)?'complete':''}" href="#lesson/${i}" aria-label="${esc(l.title)}${u.completed.includes(i)?', изучено':''}">${u.completed.includes(i)?kidIcon('check'):`<span>${i+1}</span>`}</a>`).join('')}</nav><div class="game-route-grid">${lessons.map((l,i)=>`<a class="game-stage ${u.completed.includes(i)?'complete':''}" href="#lesson/${i}"><div class="game-stage-icon">${artIcon(i)}</div><h3>${esc(l.title)}</h3><p>${['Познакомься с регионом и найди его столицу.','Узнай, как растение превращается в музыку.','Открой историю героя и познакомься со сказителями.','Загляни в лес и узнай секрет бортников.','Узнай, что объединяет людей на празднике.'][i]}</p><span class="game-stage-state">${u.completed.includes(i)?kidIcon('check')+' Открытие сохранено':'Исследовать '+kidIcon('arrow')}</span></a>`).join('')}</div></section><section class="game-finish game-panel"><div class="game-badge-icon">${kidIcon(p.studied===5?'star':'lock')}</div><div><h2>Последний шаг — испытание!</h2><p>${p.studied===5?'Ты собрал все пять открытий. Проверь себя: за четыре верных ответа получишь особый значок!':`Собери все пять открытий, чтобы открыть испытание. Осталось ${5-p.studied}.`}</p></div><div class="game-actions">${p.studied===5?'<a class="kid-primary" href="#quiz">Проверить себя '+kidIcon('arrow')+'</a>':`<a class="kid-primary" href="#lesson/${next}">К следующему открытию ${kidIcon('arrow')}</a>`}<a class="btn secondary" href="#guide">Спросить Тима</a></div></section></div>`;
}
function gameLessonPage(l,i,u){
 const completed=u.completed.includes(i);
 return `<div class="game-world"><div class="game-actions"><a class="btn secondary" href="#region">← Все остановки</a><span class="game-pill">Остановка ${i+1} из ${lessons.length}${completed?' · изучено':''}</span></div><nav class="game-trail" aria-label="Остановки маршрута">${lessons.map((v,j)=>`<a href="#lesson/${j}" class="${u.completed.includes(j)?'complete':''} ${i===j?'current':''}" ${i===j?'aria-current="step"':''} aria-label="${esc(v.title)}">${u.completed.includes(j)?kidIcon('check'):`<span>${j+1}</span>`}</a>`).join('')}</nav><div class="game-lesson-grid"><article class="game-panel game-reading"><div class="game-lesson-art">${artIcon(i)}</div><h2>${esc(l.title)}</h2><div class="game-reading-copy"><p>${esc(l.text)}</p></div><a class="game-text-link" href="#sources">Где узнать больше ${kidIcon('book')}</a></article><section class="game-panel game-challenge" aria-labelledby="challengeTitle"><div class="game-challenge-mascot"><img src="assets/lynx-guide.png" alt="" width="90" height="110"><p>Теперь твоя очередь! Выбери ответ — и сохраним открытие.</p></div><h2 id="challengeTitle">Проверь себя</h2><p class="game-question">${esc(l.question)}</p><div id="answers">${l.options.map((o,j)=>`<button type="button" class="answer" data-a="${j}"><span class="answer-letter">${'АБВГ'[j]}</span><span>${esc(o)}</span></button>`).join('')}</div><p id="feedback" role="status" aria-live="polite"></p><div id="next"></div></section></div></div>`;
}
function gameResultPage(a,u){
 const earned=a.score>=4;
 return `<div class="game-world"><section class="game-result-hero game-panel ${earned?'success':''}"><div class="game-reward-art">${kidIcon(earned?'star':'compass')}</div><div><h2>${earned?'Вот это открытие!':'Путешествие пройдено!'}</h2><p class="game-score"><strong>${a.score}</strong><span>из 5 верных ответов</span></p><p>${earned?'Значок «Исследователь Южного Урала» теперь в твоей коллекции. Тим тобой гордится!':'Ошибки тоже помогают узнавать новое. Посмотри объяснения и попробуй ещё раз: для значка нужны четыре верных ответа.'}</p><div class="game-actions"><a class="kid-primary" href="#profile">К моим открытиям ${kidIcon('arrow')}</a><a class="btn secondary" href="#quiz">Попробовать ещё раз</a></div></div></section><h2>Что мы узнали</h2><div class="game-review-grid">${lessons.map((l,i)=>{const correct=a.answers[i]===l.correct;return `<article class="game-panel game-review ${correct?'correct':'retry'}"><span class="game-review-status">${kidIcon(correct?'check':'book')}${correct?'Верно!':'Разберём вместе'}</span><h3>${esc(l.title)}</h3><p>Твой ответ: <strong>${esc(l.options[a.answers[i]]??'Нет ответа')}</strong>.</p><p>${esc(l.why)}</p><a class="btn secondary" href="#lesson/${i}">Вернуться к теме ${kidIcon('arrow')}</a></article>`}).join('')}</div></div>`;
}
function baseGameProfilePage(u){
 const p=kidProgress(u),badges=[{icon:'leaf',title:'Первый шаг',description:'Изучи одну тему.',earned:p.studied>=1},{icon:'compass',title:'Следопыт',description:'Собери пять открытий.',earned:p.studied>=5},{icon:'star',title:'Исследователь Южного Урала',description:'Ответь верно на четыре вопроса в испытании.',earned:p.best>=4}];
 return `<div class="game-world"><section class="game-profile-hero game-panel"><div class="game-avatar">${gameAvatarMarkup(u)}</div><div class="game-profile-info"><h2>${esc(u.nick)}</h2><p>${p.studied>=5?'Следопыт':'Начинающий путешественник'} · ${u.code?'класс '+esc(u.code):'самостоятельное путешествие'}</p><p>Это твой дневник. Здесь живут открытия, награды и воспоминания о путешествиях.</p><div class="game-actions"><a class="kid-primary" href="#map">За новыми открытиями ${kidIcon('arrow')}</a><a class="btn secondary" href="#wardrobe">Гардероб и рюкзак</a><a class="btn secondary" href="#character/edit">Изменить героя</a></div></div></section><div class="game-stats game-profile-stats"><div><strong>${p.xp}</strong><span>опыта собрано</span></div><div><strong>${p.studied} / 5</strong><span>учебных тем изучено</span></div><div><strong>${p.best} / 5</strong><span>лучший результат</span></div></div><section><h2>Твои значки</h2><p>Каждый значок — маленькая история о том, что ты уже умеешь.</p><div class="game-badge-grid">${badges.map(b=>`<article class="game-badge game-panel ${b.earned?'earned':''}"><span class="game-badge-icon">${kidIcon(b.icon)}${b.earned?`<i>${kidIcon('check')}</i>`:''}</span><h3>${b.title}</h3><p>${b.earned?'Получен!':b.description}</p>${b.earned?'':`<span class="game-badge-lock">${kidIcon('lock')} Ещё впереди</span>`}</article>`).join('')}</div></section><section class="game-panel game-history"><h2>Мои испытания</h2>${u.attempts.length?`<ol>${u.attempts.slice().reverse().map((a,i)=>`<li><span class="game-history-icon">${kidIcon(a.score>=4?'star':'flag')}</span><div><strong>Башкортостан</strong><span>${esc(new Date(a.date).toLocaleString('ru-RU',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}))}</span></div><b>${a.score} / 5</b>${i===0?'<a href="#result" class="game-text-link">Разбор →</a>':''}</li>`).join('')}</ol>`:'<div class="game-empty"><span>'+kidIcon('book')+'</span><p>Здесь сохраняются попытки дополнительного испытания. Его можно пройти после пяти учебных тем.</p><a class="btn secondary" href="#region">В первое путешествие →</a></div>'}</section><div class="game-actions"><a class="btn secondary" href="#login/return">Сменить ученика</a></div></div>`;
}
function gameGuidePage(){return `<div class="game-world"><div class="game-guide-grid"><section class="game-panel game-guide-card"><img src="assets/lynx-guide.png" alt="Рысёнок Тим с картой и рюкзаком" width="240" height="290"><div><h2>Привет! Я Тим.</h2><p>Знаю немало интересного о нашем маршруте. Выбирай тему — и разберёмся вместе!</p><p class="game-guide-note">Я показываю готовые справки из материалов путешествия.</p></div><a class="btn secondary" href="#region">Вернуться к маршруту →</a></section><section class="game-panel game-guide-topics"><h2>Что тебя интересует?</h2><div class="game-topic-list">${lessons.map((l,i)=>`<button type="button" class="secondary" data-guide="${i}"><span class="game-topic-icon">${artIcon(i)}</span><span>${esc(l.title)}</span>${kidIcon('arrow')}</button>`).join('')}</div><div class="game-guide-reply" id="reply" role="status" aria-live="polite"><p>Выбери любую тему выше. Я рядом!</p></div></section></div></div>`}

function gameProfilePage(u){const html=baseGameProfilePage(u),earned=u.rewards?.includes('kurai');const gifts=`<section class="game-panel game-collection"><h2>Подарки из путешествий</h2><p>${earned?'История «Праздник с Данияром» пройдена! +160 опыта.':'Каждая глава оставит память в твоём рюкзаке. Начни коллекцию с Башкортостана.'}</p><div class="story-reward-grid"><article><span class="story-reward-icon">${storyRewardIcon('kurai')}</span><h3>Значок «Курай»</h3><p>${earned?'Получен в истории с Данияром. Уже на твоём рюкзаке!':'Помоги семье Данияра подготовить праздник.'}</p></article><article><span class="story-reward-icon story-hat">${storyRewardIcon('burek')}</span><h3>Бүрек</h3><p>${earned?'Подарок для твоего путешественника.':'Головной убор откроется после прохождения главы.'}</p>${earned?`<button class="btn secondary" data-equip-burek>${u.equippedHat==='burek'?'Снять шапку':'Надеть шапку'}</button>`:''}</article></div><a class="kid-primary" href="#story">${earned?'Вернуться к истории':'Отправиться к Данияру'} ${kidIcon('arrow')}</a></section>`;return html.replace('<section><h2>Твои значки',gifts+'<section><h2>Твои значки')+`<section class="game-panel"><h2>Начать заново</h2><p>Для повторного тестирования можно удалить текущего персонажа вместе с прогрессом, открытиями и наградами и снова пройти путь с создания героя. Другие персонажи и классы сохранятся.</p><button type="button" class="btn secondary" data-reset-character>Сбросить персонажа</button></section>`}
